/**
 * TradeSathi AI — Reporting and Export Helper
 * Formats standardized trade briefs, JSON export payloads, and print summaries.
 * Always includes human-review disclaimer and non-statutory clearance statement.
 */

export const HUMAN_REVIEW_DISCLAIMER =
  'Note: Generated by TradeSathi AI. Human sign-off required prior to customs lodgement. ' +
  'Operational readiness evaluation only; not a statutory customs clearance or legal certification.'

/**
 * Generate a standard trade briefing string from a saved or current audit object.
 *
 * @param {object} result - The full audit payload
 * @returns {string} - Formatted plain text briefing
 */
export function generateAuditBrief(result) {
  if (!result) return ''

  const discText = (result.discrepancies || [])
    .map(
      (d) =>
        `• [${(d.severity || 'warning').toUpperCase()}] ${d.label || d.field}: ${d.message || d.difference || ''}\n  Action: ${d.recommended_action || 'Review and verify manually.'}`
    )
    .join('\n')

  const chkText = (result.summary?.checklist || [])
    .map(
      (c) =>
        `• [${(c.status || '').toUpperCase().replace('_', ' ')}] ${c.title || c.id}: ${c.detail || ''}`
    )
    .join('\n')

  const shipmentRef = result.shipment_reference
    ? `Shipment Reference: ${result.shipment_reference}\n`
    : result.shipment_id
      ? `Linked Shipment: ${result.shipment_id}\n`
      : 'Scope: Standalone Audit (Not linked to shipment)\n'

  const timestamp = result.created_at ? `Audit Timestamp: ${result.created_at}\n` : ''

  return `=== TRADESATHI AI SHIPMENT AUDIT BRIEF ===
ID: ${result.id}
Status: ${(result.summary?.status || result.status || '').toUpperCase()}
${timestamp}${shipmentRef}Mode: ${result.mode || 'rules_fallback'} (${result.model || 'Deterministic Rules'})
Documents: ${(result.summary?.documents_received || result.filenames || []).join(', ')}

Headline: ${result.summary?.headline || result.headline || ''}
Summary: ${result.summary?.summary_text || ''}

OPERATIONAL REVIEW CHECKLIST:
${chkText || '• None recorded.'}

DISCREPANCIES & HUMAN VERIFICATION ACTIONS:
${discText || '• None detected across evaluated fields.'}

${HUMAN_REVIEW_DISCLAIMER}`
}

/**
 * Serialize a historical or active audit object into a downloadable JSON file.
 *
 * @param {object} audit - The full analysis payload
 * @returns {{ filename: string, jsonString: string } | null}
 */
export function exportAuditJson(audit) {
  if (!audit) return null
  const filename = `tradesathi-audit-${audit.id || 'export'}.json`
  const jsonString = JSON.stringify(audit, null, 2)
  return { filename, jsonString }
}

/**
 * Sanitizes CSV cell against spreadsheet-formula injection (CSV Injection / Formula Injection).
 * Neutralizes execution in Excel, LibreOffice Calc, and Google Sheets by checking
 * whether the raw or trimmed cell begins with formula trigger characters (=, +, -, @, |, \t, \r, \n).
 * Preserves legitimate numeric values (floats, negative numbers, and integers).
 *
 * @param {any} value - Cell value to sanitize
 * @returns {string} - Escaped cell content safe for CSV serialization
 */
export function sanitizeCsvCell(value) {
  if (value === null || value === undefined) return ''
  if (typeof value === 'number') return String(value)
  const raw = String(value)
  if (!raw) return ''
  const stripped = raw.trimStart()
  if (!stripped) return ''
  if (['=', '+', '-', '@', '|'].includes(stripped[0]) || ['=', '+', '-', '@', '|', '\t', '\r', '\n'].includes(raw[0])) {
    const num = Number(stripped)
    if (!isNaN(num) && stripped !== '') {
      return raw
    }
    return "'" + raw
  }
  return raw
}

